"""字段级影响分析。

直接影响：资产的字段引用与目标字段 ``(schema, version, path)`` 精确相等。
传递影响：从资产引用的具体字段出发，沿跨 Schema ``$ref`` 边正向解析，
若能到达目标字段（精确相等、或祖先/后代包含关系），即构成传递命中。

正向解析从资产引用的 *具体* 路径出发，路径长度随跨边跳数只减不增，因此
即使 Schema 之间存在根级引用环，状态空间也是有限的。传递结果按稳定标识
``(资产, schema, version, 引用路径)`` 去重。
"""

from __future__ import annotations

from dataclasses import dataclass

from . import limits, pointer as ptr
from .errors import ImpactAnalysisTooLarge
from .registry import Registry, RefEdge


@dataclass(frozen=True)
class Reach:
    schema: str
    version: str
    path: str


def _related(a: str, b: str) -> bool:
    return a == b or ptr.is_under(a, b) or ptr.is_under(b, a)


def _build_outgoing(registry: Registry) -> dict[tuple[str, str], list[RefEdge]]:
    outgoing: dict[tuple[str, str], list[RefEdge]] = {}
    for edge in registry.all_edges():
        outgoing.setdefault((edge.src_schema, edge.src_version), []).append(edge)
    for edges in outgoing.values():
        edges.sort(
            key=lambda e: (e.dst_schema, e.dst_version, e.src_path, e.dst_path)
        )
    return outgoing


def forward_reach(
    registry: Registry,
    schema: str,
    version: str,
    path: str,
    outgoing: dict[tuple[str, str], list[RefEdge]] | None = None,
    cache: dict[tuple[str, str, str], list[Reach]] | None = None,
) -> list[Reach]:
    """从一个具体字段出发正向解析跨 Schema 引用，返回可到达的全部字段。

    每条出边满足：边的源路径与当前路径相等，或是当前路径的祖先
    （引用了包含当前字段的子树）；目标侧路径按后缀对齐。
    """
    if cache is not None:
        cached = cache.get((schema, version, path))
        if cached is not None:
            return cached
    if outgoing is None:
        outgoing = _build_outgoing(registry)

    start = Reach(schema, version, path)
    reached: dict[Reach, None] = {start: None}
    queue: list[tuple[Reach, int]] = [(start, 0)]
    edges_walked = 0

    while queue:
        state, depth = queue.pop(0)
        if depth >= limits.MAX_IMPACT_DEPTH:
            raise ImpactAnalysisTooLarge(
                "影响链深度超过公开限制",
                details={
                    "reason": "depth_exceeded",
                    "limit": limits.MAX_IMPACT_DEPTH,
                    "schema": state.schema,
                    "version": state.version,
                    "path": state.path,
                },
            )
        for edge in outgoing.get((state.schema, state.version), ()):
            sp, cp = ptr.parse(edge.src_path), ptr.parse(state.path)
            if not (len(sp) <= len(cp) and cp[: len(sp)] == sp):
                continue
            edges_walked += 1
            if edges_walked > limits.MAX_IMPACT_VISITED:
                raise ImpactAnalysisTooLarge(
                    "影响链引用边数量超过公开限制",
                    details={"reason": "edges_exceeded", "limit": limits.MAX_IMPACT_VISITED},
                )
            suffix = cp[len(sp) :]
            mapped = Reach(
                edge.dst_schema,
                edge.dst_version,
                ptr.format(list(ptr.parse(edge.dst_path)) + list(suffix)),
            )
            if mapped in reached:
                continue
            reached[mapped] = None
            queue.append((mapped, depth + 1))

    del reached[start]
    result = sorted(reached.keys(), key=lambda r: (r.schema, r.version, r.path))
    if cache is not None:
        cache[(schema, version, path)] = result
    return result


def analyze_field(registry: Registry, schema: str, version: str, path: str) -> dict:
    """返回单个字段的影响资产：直接 + 传递（各自稳定排序、去重）。"""
    registry.get_schema(schema, version)

    direct: dict[str, dict] = {}
    transitive_map: dict[tuple[str, str, str, str], dict] = {}
    outgoing = _build_outgoing(registry)
    reach_cache: dict[tuple[str, str, str], list[Reach]] = {}

    for asset in registry.all_assets():
        for ref in asset.refs:
            if ref.schema == schema and ref.version == version:
                if ref.path == path:
                    direct.setdefault(
                        asset.id,
                        {"asset_id": asset.id, "name": asset.name, "kind": asset.kind},
                    )
                    continue

            # 传递：从资产引用的具体字段正向解析到目标字段。
            reachable = forward_reach(
                registry, ref.schema, ref.version, ref.path, outgoing, reach_cache
            )
            matched = [r for r in reachable if r.schema == schema and r.version == version
                       and _related(r.path, path)]
            if not matched:
                continue
            key = (asset.id, ref.schema, ref.version, ref.path)
            entry = transitive_map.get(key)
            if entry is None:
                entry = {
                    "asset_id": asset.id,
                    "name": asset.name,
                    "kind": asset.kind,
                    "schema": ref.schema,
                    "version": ref.version,
                    "path": ref.path,
                    "matched_paths": [],
                }
                transitive_map[key] = entry
            for r in matched:
                if r.path not in entry["matched_paths"]:
                    entry["matched_paths"].append(r.path)

    transitive = list(transitive_map.values())
    for entry in transitive:
        entry["matched_paths"].sort(key=lambda p: (ptr.parse(p), p))

    if len(direct) + len(transitive) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "影响资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )

    return {
        "schema": schema,
        "version": version,
        "path": path,
        "direct_assets": [direct[k] for k in sorted(direct)],
        "transitive_assets": sorted(
            transitive,
            key=lambda a: (a["asset_id"], a["schema"], a["version"], a["path"]),
        ),
    }

"""注册簿：Schema 版本、目录资产与跨 Schema 引用关系。

注册内容不可变：任何读取都返回深拷贝，比较、影响分析和检索都无法改动
既有注册结果、版本关系与资产依赖关系。

跨 Schema 引用约定：``$ref`` 写作 ``"<SchemaName>@<version>#<JSONPointer>"``，
例如 ``"Address@1.0#/properties/street"``；``#`` 后为空表示引用文档根。
文档内引用沿用标准 ``"#/..."`` 形式。
"""

from __future__ import annotations

import copy
import re
from dataclasses import dataclass
from typing import Any

from .errors import AlreadyExistsError, NotFoundError
from . import pointer as ptr
from .schema_fields import expand as _expand_fields

_REF_RE = re.compile(r"^(?P<name>[^@#/\s]+)@(?P<version>[^@#\s]+)#(?P<pointer>.*)$")
_NAME_RE = re.compile(r"^[A-Za-z0-9_.\-]+$")


def validate_name(name: str, *, what: str = "名称") -> None:
    if not isinstance(name, str) or not name or not _NAME_RE.match(name):
        raise ValueError(f"非法{what}: {name!r}（只允许字母、数字、_、.、-）")


@dataclass(frozen=True)
class SchemaVersion:
    name: str
    version: str
    document: Any
    title: str | None


@dataclass(frozen=True)
class FieldRef:
    """资产对某 Schema 某版本某字段路径的直接引用。"""

    schema: str
    version: str
    path: str  # JSON Pointer，"" 表示根


@dataclass(frozen=True)
class Asset:
    id: str
    name: str
    kind: str
    refs: tuple[FieldRef, ...]


@dataclass(frozen=True)
class RefEdge:
    """一条跨 Schema ``$ref`` 边：src 字段定义引用了 dst 字段节点。"""

    src_schema: str
    src_version: str
    src_path: str
    dst_schema: str
    dst_version: str
    dst_path: str


def parse_external_ref(ref: str) -> tuple[str, str, str] | None:
    """解析跨 Schema 引用；非此外部形式返回 ``None``。"""
    m = _REF_RE.match(ref)
    if not m:
        return None
    return m.group("name"), m.group("version"), m.group("pointer")


def extract_ref_edges(name: str, version: str, document: Any) -> list[RefEdge]:
    """提取文档内全部跨 Schema 引用边（原始文档指针，按出现顺序排序）。

    指针在注册时再结合两端文档解析为逻辑字段路径。
    """
    edges: list[RefEdge] = []

    def walk(node: Any, path: str, seen: frozenset[int]) -> None:
        if isinstance(node, bool) or not isinstance(node, (dict, list)):
            return
        if id(node) in seen:
            return
        seen = seen | {id(node)}
        if isinstance(node, dict):
            ref = node.get("$ref")
            if isinstance(ref, str):
                parsed = parse_external_ref(ref)
                if parsed is not None:
                    dst_name, dst_version, fragment = parsed
                    if fragment and not fragment.startswith("/"):
                        fragment = "/" + fragment
                    edges.append(
                        RefEdge(name, version, path, dst_name, dst_version, fragment)
                    )
            for k in sorted(node.keys()):
                walk(node[k], path + "/" + _escape(k) if path else "/" + _escape(k), seen)
        else:
            for i, v in enumerate(node):
                walk(v, f"{path}/{i}" if path else f"/{i}", seen)

    walk(document, "", frozenset())
    edges.sort(key=lambda e: (e.src_path, e.dst_schema, e.dst_version, e.dst_path))
    return edges


def _escape(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")


class Registry:
    def __init__(self) -> None:
        self._schemas: dict[tuple[str, str], SchemaVersion] = {}
        # name -> 按注册顺序保存的版本列表
        self._versions: dict[str, list[str]] = {}
        self._assets: dict[str, Asset] = {}
        self._edges: dict[tuple[str, str], tuple[RefEdge, ...]] = {}

    # ------------------------------------------------------------------ schema
    def register_schema(self, name: str, version: str, document: Any) -> SchemaVersion:
        validate_name(name, what="Schema 名称")
        validate_name(version, what="版本号")
        key = (name, version)
        if key in self._schemas:
            raise AlreadyExistsError(
                f"Schema {name}@{version} 已注册，注册内容不可覆盖",
                details={"schema": name, "version": version},
            )
        # 跨 Schema 引用允许前向（目标稍后注册），因此引用环也可注册；
        # 目标缺失或目标字段不存在时，影响传播自然不会产生命中。
        raw_edges = extract_ref_edges(name, version, document)
        edges: list[RefEdge] = []
        for e in raw_edges:
            dst_record = self._schemas.get((e.dst_schema, e.dst_version))
            dst_raw = e.dst_path if e.dst_path else ""
            if dst_record is not None:
                dst_logical = ptr.resolve_logical(dst_record.document, dst_raw)
                if dst_logical is None or dst_logical not in _expand_fields(dst_record.document):
                    # 目标已注册但字段不存在：属于确定的非法引用。
                    raise NotFoundError(
                        f"跨 Schema 引用 {e.dst_schema}@{e.dst_version}{dst_raw} 的目标字段不存在",
                        details={
                            "schema": e.dst_schema,
                            "version": e.dst_version,
                            "path": dst_raw,
                        },
                    )
                final_dst = dst_logical
            else:
                final_dst = ptr.normalize_field_pointer(dst_raw)
            src_logical = ptr.resolve_logical(document, e.src_path)
            edges.append(
                RefEdge(
                    name,
                    version,
                    src_logical or ptr.normalize_field_pointer(e.src_path),
                    e.dst_schema,
                    e.dst_version,
                    final_dst,
                )
            )
        edges.sort(key=lambda x: (x.src_path, x.dst_schema, x.dst_version, x.dst_path))
        title = None
        if isinstance(document, dict):
            t = document.get("title")
            title = t if isinstance(t, str) else None
        record = SchemaVersion(name, version, copy.deepcopy(document), title)
        self._schemas[key] = record
        self._versions.setdefault(name, []).append(version)
        self._edges[key] = tuple(edges)
        return record

    def get_schema(self, name: str, version: str) -> SchemaVersion:
        key = (name, version)
        if key not in self._schemas:
            raise NotFoundError(
                f"Schema {name}@{version} 不存在",
                details={"schema": name, "version": version},
            )
        return self._schemas[key]

    def has_schema(self, name: str, version: str) -> bool:
        return (name, version) in self._schemas

    def schema_document(self, name: str, version: str) -> Any:
        return copy.deepcopy(self.get_schema(name, version).document)

    def list_versions(self, name: str) -> list[str]:
        if name not in self._versions:
            raise NotFoundError(f"Schema {name} 不存在", details={"schema": name})
        return list(self._versions[name])

    def edges(self, name: str, version: str) -> tuple[RefEdge, ...]:
        return self._edges.get((name, version), ())

    def all_edges(self) -> list[RefEdge]:
        out: list[RefEdge] = []
        for key in sorted(self._edges):
            out.extend(self._edges[key])
        return out

    def all_schemas(self) -> list[SchemaVersion]:
        return [self._schemas[k] for k in sorted(self._schemas)]

    def registered_pairs(self) -> list[tuple[str, str]]:
        """按全局注册顺序返回全部 ``(名称, 版本)``。"""
        return list(self._schemas.keys())

    def _logical_path_exists(
        self, schema: str, version: str, path: str, stack: frozenset[tuple[str, str]]
    ) -> bool:
        """判断逻辑字段路径是否可达，沿跨 Schema ``$ref`` 边跳转解析。"""
        if (schema, version) not in self._schemas:
            return False
        document = self._schemas[(schema, version)].document
        valid_paths = _expand_fields(document)
        if path in valid_paths:
            return True

        target_segs = ptr.parse(path)
        # 选择最长的、能覆盖目标路径前缀的出边。
        best = None
        for edge in self._edges.get((schema, version), ()):  # type: RefEdge
            esegs = ptr.parse(edge.src_path)
            if len(esegs) <= len(target_segs) and target_segs[: len(esegs)] == esegs:
                if best is None or len(esegs) > len(ptr.parse(best.src_path)):
                    best = edge
        if best is None:
            return False
        dst_key = (best.dst_schema, best.dst_version)
        if dst_key in stack:
            return False
        suffix = target_segs[len(ptr.parse(best.src_path)) :]
        resolved = ptr.format(list(ptr.parse(best.dst_path)) + list(suffix))
        return self._logical_path_exists(
            best.dst_schema, best.dst_version, resolved, stack | {dst_key}
        )

    # ------------------------------------------------------------------- asset
    def register_asset(
        self,
        asset_id: str,
        name: str,
        kind: str,
        refs: list[FieldRef] | list[dict] | None = None,
    ) -> Asset:
        validate_name(asset_id, what="资产标识")
        if not isinstance(name, str) or not name:
            raise ValueError("资产名称必须是非空字符串")
        if not isinstance(kind, str) or not kind:
            raise ValueError("资产类型必须是非空字符串")
        if asset_id in self._assets:
            raise AlreadyExistsError(
                f"资产 {asset_id} 已注册", details={"asset": asset_id}
            )

        normalized: list[FieldRef] = []
        seen: set[tuple[str, str, str]] = set()
        for raw in refs or []:
            if isinstance(raw, FieldRef):
                r = raw
            else:
                r = FieldRef(raw["schema"], str(raw["version"]), raw.get("path", ""))
            validate_name(r.schema, what="引用 Schema 名称")
            record = self.get_schema(r.schema, r.version)
            if r.path and not r.path.startswith("/"):
                raise ValueError(f"资产引用字段路径必须是 JSON Pointer: {r.path!r}")
            candidate_paths = []
            contextual = ptr.resolve_logical(record.document, r.path)
            if contextual is not None:
                candidate_paths.append(contextual)
            text_normalized = ptr.normalize_field_pointer(r.path)
            for cand in (text_normalized, r.path):
                if cand not in candidate_paths:
                    candidate_paths.append(cand)

            resolved_path = next(
                (
                    cand
                    for cand in candidate_paths
                    if self._logical_path_exists(
                        r.schema, r.version, cand, frozenset({(r.schema, r.version)})
                    )
                ),
                None,
            )
            if resolved_path is None:
                raise NotFoundError(
                    f"资产引用的字段 {r.schema}@{r.version}{text_normalized} 不存在",
                    details={
                        "schema": r.schema,
                        "version": r.version,
                        "path": text_normalized,
                    },
                )
            r = FieldRef(r.schema, r.version, resolved_path)
            dedup_key = (r.schema, r.version, r.path)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)
            normalized.append(r)

        normalized.sort(key=lambda r: (r.schema, r.version, r.path))
        asset = Asset(asset_id, name, kind, tuple(normalized))
        self._assets[asset_id] = asset
        return asset

    def get_asset(self, asset_id: str) -> Asset:
        if asset_id not in self._assets:
            raise NotFoundError(f"资产 {asset_id} 不存在", details={"asset": asset_id})
        return self._assets[asset_id]

    def all_assets(self) -> list[Asset]:
        return [self._assets[k] for k in sorted(self._assets)]

"""字段路径工具。

字段路径采用 JSON Pointer（RFC 6901）表示，例如 ``/properties/name``、
``/properties/a~1b``。根对象本身用空串 ``""`` 表示。
"""

from __future__ import annotations

from typing import Any


def escape(token: str) -> str:
    """转义单个路径段。"""
    return token.replace("~", "~0").replace("/", "~1")


def unescape(token: str) -> str:
    """反转义单个路径段。"""
    return token.replace("~1", "/").replace("~0", "~")


def parse(path: str) -> tuple[str, ...]:
    """把 JSON Pointer 解析为路径段元组；根路径返回空元组。"""
    if path == "":
        return ()
    if not path.startswith("/"):
        raise ValueError(f"非法 JSON Pointer: {path!r}")
    return tuple(unescape(seg) for seg in path[1:].split("/"))


def format(segments: tuple[str, ...] | list[str]) -> str:
    """把路径段组装为 JSON Pointer。"""
    return "".join("/" + escape(str(seg)) for seg in segments)


def child(path: str, segment: str) -> str:
    """返回某路径下的子路径。"""
    return (path + "/" + escape(segment)) if path else "/" + escape(segment)


def parent(path: str) -> str | None:
    """返回父路径；根路径返回 ``None``。"""
    segs = parse(path)
    if not segs:
        return None
    return format(segs[:-1])


def is_under(prefix: str, path: str) -> bool:
    """``path`` 是否位于 ``prefix`` 子树内（含自身）。"""
    p, c = parse(prefix), parse(path)
    return len(c) >= len(p) and c[: len(p)] == p


def resolve(doc: Any, path: str) -> Any:
    """在文档中按 JSON Pointer 取值，缺段/越界/类型不符时抛 KeyError。"""
    cur: Any = doc
    for seg in parse(path):
        if isinstance(cur, dict):
            if seg not in cur:
                raise KeyError(path)
            cur = cur[seg]
        elif isinstance(cur, list):
            try:
                idx = int(seg)
            except ValueError as exc:
                raise KeyError(path) from exc
            if not 0 <= idx < len(cur):
                raise KeyError(path)
            cur = cur[idx]
        else:
            raise KeyError(path)
    return cur


def normalize_field_pointer(path: str) -> str:
    """把 Schema 文档指针 *无上下文地* 规整为逻辑字段路径。

    注意：纯文本规整无法区分「名为 ``items`` 的属性」与 ``items`` 关键字，
    资产/引用路径应优先使用逻辑路径，或用 :func:`resolve_logical` 结合
    文档解析。
    """
    segs = list(parse(path))
    out: list[str] = []
    for i, seg in enumerate(segs):
        if seg in ("properties", "prefixItems"):
            continue
        if seg == "additionalProperties":
            out.append("*")
        elif seg == "items":
            # 元组形式 items/0 展开为数组下标；单 Schema items 展开为 -。
            if i + 1 < len(segs) and segs[i + 1].isdigit():
                continue
            out.append("-")
        else:
            out.append(seg)
    return format(out)


def resolve_logical(document: Any, raw_path: str) -> str | None:
    """结合文档结构，把文档指针解析为逻辑字段路径；不可解析返回 ``None``。

    遍历规则与字段展开一致：``properties`` 段省略（其后必为属性名，即使
    名字恰好叫 ``items``）；单 Schema ``items`` 段映射为 ``-``；
    ``additionalProperties`` 映射为 ``*``；``$defs``/``definitions`` 保留。
    """
    segs = parse(raw_path)
    node: Any = document
    logical: list[str] = []
    i = 0
    while i < len(segs):
        seg = segs[i]
        if isinstance(node, dict):
            props = node.get("properties")
            if seg == "properties" and isinstance(props, dict):
                # 容器关键字与其后的属性名在同一步消费，避免属性名与
                # Schema 关键字（如名为 items 的属性）混淆。
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in props:
                    return None
                node = props[name]
                logical.append(name)
                i += 2
                continue
            pats = node.get("patternProperties")
            if seg == "patternProperties" and isinstance(pats, dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in pats:
                    return None
                node = pats[name]
                logical.append(escape(name))
                i += 2
                continue
            ap = node.get("additionalProperties")
            if seg == "additionalProperties" and isinstance(ap, (dict, bool)):
                node = ap
                logical.append("*")
                i += 1
                continue
            items = node.get("items")
            if seg == "items" and isinstance(items, (dict, bool)):
                node = items
                logical.append("-")
                i += 1
                continue
            pre = node.get("prefixItems")
            if seg == "prefixItems" and isinstance(pre, list):
                if i + 1 >= len(segs):
                    return None
                try:
                    idx = int(segs[i + 1])
                except ValueError:
                    return None
                if not 0 <= idx < len(pre):
                    return None
                node = pre[idx]
                logical.append(str(idx))
                i += 2
                continue
            if seg in ("$defs", "definitions") and isinstance(node.get(seg), dict):
                if i + 1 >= len(segs):
                    return None
                name = segs[i + 1]
                if name not in node[seg]:
                    return None
                node = node[seg][name]
                logical.extend((seg, name))
                i += 2
                continue
            if seg not in node:
                return None
            node = node[seg]
            logical.append(seg)
            i += 1
        elif isinstance(node, list):
            try:
                idx = int(seg)
            except ValueError:
                return None
            if not 0 <= idx < len(node):
                return None
            node = node[idx]
            logical.append(seg)
            i += 1
        else:
            return None
    return format(logical)

"""把 JSON Schema 展开为扁平字段表，并给出字段特征。

只展开业务字段所在的容器：根节点、``properties``、``$defs``/``definitions``
里的对象、以及 ``items``/``prefixItems``/``additionalProperties`` 等容器层。
``allOf``/``anyOf``/``oneOf`` 等组合子节点不参与字段路径比较（避免同一逻辑
字段出现多重路径），但其 ``required`` 约束会被合并到所在对象节点。
"""

from __future__ import annotations

import json
from typing import Any

from . import pointer as ptr

# 纯注解关键字：只调整这些时归类为 metadata。
ANNOTATION_KEYS = ("title", "description", "$comment")

# 结构关键字（参与兼容判定）。顺序同时决定摘要输出顺序，保证确定性。
STRUCTURAL_KEYS = (
    "type",
    "enum",
    "const",
    "required",
    "default",
    "format",
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "multipleOf",
    "minLength",
    "maxLength",
    "pattern",
    "minItems",
    "maxItems",
    "uniqueItems",
    "minProperties",
    "maxProperties",
)

# 嵌套容器关键字：不在同路径字段比较范围内，由子字段条目负责。
CONTAINER_KEYS = frozenset(
    {
        "properties",
        "patternProperties",
        "additionalProperties",
        "items",
        "prefixItems",
        "contains",
        "allOf",
        "anyOf",
        "oneOf",
        "not",
        "$defs",
        "definitions",
        "$ref",
        "propertyNames",
        "unevaluatedProperties",
        "unevaluatedItems",
    }
)

# 放宽/收窄判定关心的数值边界关键字。
_BOUND_KEYS = (
    "minimum",
    "maximum",
    "exclusiveMinimum",
    "exclusiveMaximum",
    "minLength",
    "maxLength",
    "minItems",
    "maxItems",
    "minProperties",
    "maxProperties",
    "pattern",
    "format",
    "multipleOf",
    "uniqueItems",
)


class Field:
    """一个展开后的字段节点。

    :ivar path: 字段的 JSON Pointer 路径。
    :ivar schema: 该字段的生效 Schema 片段（已合并 allOf/required）。
    :ivar required_paths: 该对象节点直接要求必填的子字段路径集合。
    """

    __slots__ = ("path", "schema", "required_paths")

    def __init__(self, path: str, schema: dict, required_paths: frozenset[str]):
        self.path = path
        self.schema = schema
        self.required_paths = required_paths


def _effective(node: dict) -> dict:
    """返回字段的生效定义：合并 allOf 的结构关键字与 required。

    不改变原节点；不递归 anyOf/oneOf（分支为可选，不构成确定约束）。
    """
    merged: dict[str, Any] = {k: v for k, v in node.items() if k != "allOf"}
    required: list[Any] = list(node.get("required", []))
    for sub in node.get("allOf", []) or []:
        if not isinstance(sub, dict):
            continue
        for k, v in sub.items():
            if k == "required":
                required.extend(v)
            elif k == "allOf":
                continue
            elif k not in merged:
                merged[k] = v
    if required:
        # 去重但保持稳定顺序。
        seen: set[str] = set()
        uniq = []
        for r in required:
            if r not in seen:
                seen.add(r)
                uniq.append(r)
        merged["required"] = uniq
    return merged


def expand(document: Any) -> dict[str, Field]:
    """把文档展开为 ``{path: Field}``。"""
    fields: dict[str, Field] = {}
    if isinstance(document, bool):
        fields[""] = Field("", {} if document else {}, frozenset())
        return fields

    def add(path: str, raw: Any) -> None:
        if isinstance(raw, bool):
            raw = {} if raw else {"not": {}}
        eff = _effective(raw)
        req = frozenset(
            ptr.child(path, name)
            for name in eff.get("required", [])
            if isinstance(name, str)
        )
        fields[path] = Field(path, eff, req)

    def walk(node: Any, path: str, seen: frozenset[int]) -> None:
        if isinstance(node, bool):
            add(path, node)
            return
        if not isinstance(node, dict):
            return
        if id(node) in seen:
            return
        seen = seen | {id(node)}

        add(path, node)
        eff = fields[path].schema

        for name in sorted(eff.get("properties", {}).keys()):
            walk(eff["properties"][name], ptr.child(path, name), seen)

        for def_kw in ("$defs", "definitions"):
            defs = eff.get(def_kw)
            if isinstance(defs, dict):
                for dname in sorted(defs.keys()):
                    sub = defs[dname]
                    if isinstance(sub, dict) or isinstance(sub, bool):
                        walk(sub, ptr.child(ptr.child(path, def_kw), dname), seen)

        items = eff.get("items")
        if isinstance(items, dict):
            walk(items, ptr.child(path, "-"), seen)
        elif isinstance(items, list):
            for i, sub in enumerate(items):
                if isinstance(sub, dict):
                    walk(sub, path + "/" + str(i), seen)
        for i, sub in enumerate(eff.get("prefixItems", []) or []):
            if isinstance(sub, dict):
                walk(sub, path + "/" + str(i), seen)
        ap = eff.get("additionalProperties")
        if isinstance(ap, dict):
            walk(ap, path + "/*", seen)
        pp = eff.get("patternProperties")
        if isinstance(pp, dict):
            for name in sorted(pp.keys()):
                sub = pp[name]
                if isinstance(sub, dict):
                    walk(sub, path + "/" + ptr.escape(name), seen)

    walk(document, "", frozenset())
    return fields


def summary(field_schema: dict) -> dict[str, Any]:
    """字段定义摘要：确定性的、可 JSON 序列化的结构关键字快照。"""
    out: dict[str, Any] = {}
    for key in STRUCTURAL_KEYS:
        if key in field_schema:
            out[key] = _canonical(field_schema[key])
    return out


def _canonical(value: Any) -> Any:
    """把取值转为可比较、可 JSON 序列化的规范形式。"""
    return json.loads(json.dumps(value, sort_keys=True, ensure_ascii=False))


# ---------------------------------------------------------------------------
# 特征提取与兼容判定
# ---------------------------------------------------------------------------


def _types(schema: dict) -> frozenset[str]:
    t = schema.get("type")
    if t is None:
        return frozenset()
    return frozenset(t if isinstance(t, list) else [t])


def _enum(schema: dict):
    if "enum" in schema:
        return tuple(json.dumps(v, sort_keys=True, ensure_ascii=False) for v in schema["enum"])
    if "const" in schema:
        return (json.dumps(schema["const"], sort_keys=True, ensure_ascii=False),)
    return None


def _bounds(schema: dict) -> dict[str, Any]:
    return {k: _canonical(schema[k]) for k in _BOUND_KEYS if k in schema}


def annotation_signature(schema: dict) -> dict[str, Any]:
    return {k: schema[k] for k in ANNOTATION_KEYS if k in schema}


# 兼容内部旧命名。
_annotation_signature = annotation_signature


def structural_signature(schema: dict) -> dict[str, Any]:
    """同路径字段的结构特征（排除注解、嵌套容器与 required）。

    嵌套容器由各自展开出的子字段条目负责；required 变化由编排层按
    子字段生成 required_added/required_removed 条目。
    """
    return {
        k: _canonical(v)
        for k, v in schema.items()
        if k not in ANNOTATION_KEYS and k not in CONTAINER_KEYS and k != "required"
    }


def classify_pair(old: dict, new: dict) -> str:
    """比较同一路径字段的新旧 *结构* 定义，返回兼容结论。

    仅当结构签名确实不同时调用（注解-only 变化由编排层判为 metadata）。

    约定：
      * 放宽枚举、integer→number、增加默认值 → compatible；
      * 收窄类型/枚举、允许原本不接受的 null、新增约束 → breaking；
      * 同时有收有放按 breaking。
    """
    if structural_signature(old) == structural_signature(new):
        return "metadata"

    verdicts: list[str] = []

    # 1) 类型：integer -> number 放宽；出现新增的 null 为破坏性；其余集合变化收紧/扩展。
    ot, nt = _types(old), _types(new)
    if nt != ot:
        if ot == frozenset({"integer"}) and nt == frozenset({"number"}):
            verdicts.append("compatible")
        else:
            added = nt - ot
            if "null" in added:
                verdicts.append("breaking")
            elif ot and not nt:
                verdicts.append("compatible")  # 取消类型约束 = 放宽
            elif ot and nt and nt > ot:
                verdicts.append("compatible")  # 类型集合扩大
            elif not ot:
                # 旧未约束类型、新给出具体类型：视为收窄。
                verdicts.append("breaking")
            else:
                verdicts.append("breaking")

    # 2) 枚举/const：取值集合扩大为放宽，缩小为收窄。
    oe, ne = _enum(old), _enum(new)
    if oe != ne:
        if oe is None and ne is None:
            pass
        elif oe is not None and ne is not None:
            oset, nset = frozenset(oe), frozenset(ne)
            verdicts.append("compatible" if oset < nset else "breaking")
        elif ne is None:
            verdicts.append("compatible")  # 取消枚举 = 放宽
        else:
            verdicts.append("breaking")  # 新增强枚举 = 收窄

    # 3) 数值/长度等边界：逐项比较。
    ob, nb = _bounds(old), _bounds(new)
    if ob != nb:
        verdicts.extend(_classify_bounds(ob, nb))

    # 4) default：增加默认值明确属于兼容；移除或改变默认值会让依赖缺省
    #    行为的数据发生变化，保守归为破坏性。
    if "default" in new and "default" not in old:
        verdicts.append("compatible")
    elif old.get("default") != new.get("default"):
        verdicts.append("breaking")

    # 5) 其余结构键（未知/新增约束键）：出现即为新增约束 → breaking；
    #    消失为放宽 → compatible。
    known = set(STRUCTURAL_KEYS) | set(ANNOTATION_KEYS) | {"default"}

    def is_extra(k: str) -> bool:
        return (
            k not in known
            and not k.startswith("$")
            and k not in CONTAINER_KEYS
        )

    extra_o = {k for k in old if is_extra(k)}
    extra_n = {k for k in new if is_extra(k)}
    if extra_n - extra_o:
        verdicts.append("breaking")
    if extra_o - extra_n:
        verdicts.append("compatible")

    if "breaking" in verdicts:
        return "breaking"
    if "compatible" in verdicts:
        return "compatible"
    return "metadata"


def _classify_bounds(ob: dict, nb: dict) -> list[str]:
    """对数值边界做放宽/收窄判定。

    lower 类关键字（minimum 等）减小为放宽；upper 类增大为放宽；
    pattern/format/multipleOf/uniqueItems 出现或收紧为 breaking。
    """
    out: list[str] = []
    lower = ("minimum", "exclusiveMinimum", "minLength", "minItems", "minProperties")
    upper = ("maximum", "exclusiveMaximum", "maxLength", "maxItems", "maxProperties")

    for key in sorted(set(ob) | set(nb)):
        ov, nv = ob.get(key), nb.get(key)
        if ov == nv:
            continue
        if nv is None:
            out.append("compatible")  # 移除边界 = 放宽
            continue
        if ov is None:
            out.append("breaking")  # 新增边界 = 收窄
            continue
        if key in lower:
            out.append("compatible" if nv < ov else "breaking")
        elif key in upper:
            out.append("compatible" if nv > ov else "breaking")
        else:
            # pattern / format / multipleOf / uniqueItems：改变既有约束 = 收窄。
            out.append("breaking")
    return out

